import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Runnable;

class Example {
    AtomicInteger counter = new AtomicInteger(0);

    public void runTask() {
        Runnable task = () -> counter.incrementAndGet();
        execute(task);
    }

    private void execute(Runnable r) {
        r.run();
    }
}

