negativeExample:
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Runnable;
import java.util.function.Consumer;

class Example {
    AtomicInteger counter = new AtomicInteger(0);

    public void runTask() {
        // Not a simple method call, multiple statements
        Runnable task1 = () -> {
            counter.incrementAndGet();
            System.out.println("Done");
        };
        execute(task1);

        // Lambda takes arguments, not '() -> ...'
        Consumer<Integer> task2 = (val) -> counter.addAndGet(val);
        executeConsumer(task2, 1);

        // Body is not a method call on a target
        Runnable task3 = () -> System.out.println("Hello");
        execute(task3);
    }

    private void execute(Runnable r) {
        r.run();
    }

    private void executeConsumer(Consumer<Integer> c, int val) {
        c.accept(val);
    }
}
